-- wave-seminyak-kuta-bali-2026-10-08: 220 field(s) in one DO block, one UPDATE per column.
-- Each UPDATE must change exactly the number of rows it lists; if one does not, the whole block rolls back.
-- Generated 2026-10-08 by scripts/copy/build-copy-sql.mjs. Guards: md5 of the current text; every literal is ASCII.
do $apply$
declare n int;
begin
  update venues v set why_its_here = d.val
  from (values
    ('anika-gym', 'c69cec01cb23d6e83515672cf7124903', 'A no-frills local gym in Padangsambian Klod, Denpasar, with rock-bottom prices. It''s on Jl. Gn. Tangkuban Perahu, and enquiries and sign-up go through WhatsApp or the @anika_fitness_club Instagram account.'),
    ('azul-beach-club-legian', 'f581112770f5bf559f9b775c4e69227a', 'A bamboo tree-house beach club on the Legian beachfront, built over three open-air tiered levels that face the ocean. It has its own Tiki bar, and the kitchen does playful takes on Indonesian classics.'),
    ('babi-guling-pak-malen', 'd8f33be5813aa97bb7bfc9af2fec0f48', 'Pak Malen''s warung serves essentially one thing: nasi campur babi guling, Balinese roast suckling pig with rice. The plate comes with crispy skin, pork satay and green-chili sambal. It typically sells out by early afternoon.'),
    ('bali-barber-seminyak-seminyak', '8c6573f5aa4a5e4125701b38b91a76fd', 'The Seminyak branch of Bali Barber, a premium men''s barbershop brand whose original location dates from 2012. English-speaking master barbers do scissor cuts, clipper fades, hot-towel shaves and beard work, with add-ons such as facials and massage. It shares a building with The Shampoo Lounge.'),
    ('bali-fitness-seminyak-seminyak', '7efbcd5080bc1a86debc93c87c7299e0', 'On Sunset Road, a full-service gym that runs Les Mills group classes. There''s a dedicated bike and spin studio, a fully equipped weights-and-cardio floor, and personal training.'),
    ('bali-green-surf', '7869c494c1aada759b97a9b1b34bfbf5', 'A surf school on Kuta beach that runs instructor-led lessons and rents boards on the same beginner-friendly break. It''s a straightforward way to get in the water with guidance.'),
    ('bambu', '6c3713bb4e6ad755f15625613249691c', 'The La Lucciola team runs this dinner-only Indonesian restaurant on Jl. Petitenget. Tables sit in open-air pavilions around a koi pond, across a candlelit garden. The kitchen cooks regional recipes from the archipelago: slow-roasted betutu duck, sambals and babi guling.'),
    ('biku', '4ec603ac80015b5a52e21c661fda530b', 'Inside a 150-year-old teak joglo on Petitenget, Biku is a tea lounge, restaurant and antique bookstore at once. High tea comes in traditional, Asian and breakfast versions, and there are 50-plus teas from China, India and Indonesia. The menu is Indonesian and Western.'),
    ('bodyworks-beauty-seminyak-seminyak', '8fcc984341b397f48a5a2163a2bddb68', U&'The beauty side of Bodyworks, a Seminyak spa on Jl. Kayu Jati in Petitenget. It does nails, waxing, facials and hair daily, 9:00\201322:00.'),
    ('bodyworks-spa-seminyak', '5bc3489e8a1437ee6bd5b5f59934dc60', 'A Seminyak day spa, open for over two decades, now in a pink Moroccan-style building with a central pool. The full massage and spa menu sits alongside hair, nails, facials and waxing under one roof.'),
    ('bossman-burgers', '2d0daa1931572ac8b41bce8474f5c907', 'This Seminyak burger joint serves until roughly 5am, which makes it a post-night-out stop. The patties are Australian beef, smash or gourmet, with house-made sauces and freshly baked buns.'),
    ('boyncow', '9afcf33a7d54a1e040dbdbffae004e90', 'Boy''N''Cow has been a steakhouse and cocktail lounge on Seminyak''s Eat Street (Jl. Raya Kerobokan) since 2017. Cuts are dry-aged on site for at least 30 days; the Wagyu is Australian, US and Japanese, A5 included. A mezzanine speakeasy pours barrel-aged cocktails and single malts.'),
    ('caseys-spa-beauty-salon-legian', 'f657037e72932afdac5b010522e2a852', 'This spa and beauty salon on Jalan Melasti sits opposite Legian Beach Hotel. It does Balinese massage, facials, body scrubs, manicures and pedicures, plus hair treatments.'),
    ('coffee-cartel-legian', '554829a0d9bbefaec3cb2ff81ce0a75f', 'Part of a small Bali chain, this Legian specialty-coffee spot pours premium blends alongside the classics. The unusual lattes are made with matcha, charcoal or beetroot.'),
    ('corner-house-bali', '324917c749b7954d6fc19ab525d5ff8c', 'An all-day cafe and bistro in a colonial house on the corner of Oberoi Road, on Seminyak''s Eat Street. The cooking is casual Western and modern Australian: breakfast and brunch, then burgers, char-grilled steaks and pizza.'),
    ('crossfit-seminyak', '521bbdc03a3b63bef0867db995a86e5d', 'An open-air CrossFit box with classes in CrossFit, bootcamp, movement, mobility and olympic lifting. The kit runs to rigs, bumpers, rowers and assault bikes. Showers and towels are provided, and classes are in English.'),
    ('desa-potato-head-wellness', '0abeebd5dcd748e2d0c46832fb5e8f00', 'Desa Potato Head''s wellbeing programme on Jl. Petitenget runs all-level yoga: free for Suites and Studios guests, by donation for others. Its Sanctuary was built with the founders of Pyramids of Chi in Ubud and runs vibroacoustic light therapy, sound healing, breathwork and ice baths.'),
    ('desa-wisata-penglipuran', 'ac6bee2cda7228023d06f93e94ab19df', 'Penglipuran is a traditional Bali Aga village in Bangli. Its houses are uniform and bamboo-roofed, and the main street is car-free.'),
    ('desa-wisata-tembuku', '9721a93740ca3450bcf1b743849ca10f', 'Rice terraces and forest surround Tembuku, a village in Bangli. It is home to Tukad Cepung waterfall, roughly 8km from Bangli town, where water falls through a narrow rock crevice about 15 metres high.'),
    ('desa-wisata-tenganan', 'e5f2e408a3fde56e4ae32e9ff2e957f2', 'Tenganan, in Karangasem, is a Bali Aga village; the Bali Aga are the indigenous pre-Hindu Balinese. Double-ikat geringsing cloth is woven here.'),
    ('desa-wisata-undisan', 'bb36a3f520ea284393340b02dcccccab', 'Undisan, a traditional village in Bangli, is about 90 minutes from Ngurah Rai airport or 45 minutes from Ubud. Its traditions include matekap, ploughing rice fields with oxen, and gold-and-silver flower craftwork. Air Terjun Tangkup waterfall is roughly a 45-minute walk from the main road.'),
    ('drifter-kayu-aya', '4091a20c1e0c428d004e2d92d6145c3c', 'Surfers Tim Russo and Jake MacKenzie opened this surf shop, cafe and bookstore on Jl. Kayu Aya in 2009. It sells hand-shaped boards and independent brands alongside books and artwork, and the coffee is Sumatran. Gallery openings, film screenings and live music run in season.'),
    ('engine-room-legian', 'fb345504ac241f68d9001a3c3cb7b2fd', 'A three-storey nightclub on the Legian strip. The main dance floor opens straight onto the sidewalk, and resident DJs play hip-hop, dubstep and trap.'),
    ('fire-restaurant-seminyak', 'c05af0ae9943f80d19941bf2122eee84', U&'An open-fire kitchen in Seminyak that takes bookings on its own site. The published menu runs to 52 priced items; flatbread comes with za\2019atar and honey yogurt, and sourdough with brown butter. Lombok oysters with green apple, mint vinaigrette and sea fennel are 75K IDR.'),
    ('gambinos-bali', '50f74c64f76ff4b949a404ac516e4fe9', 'A premium Seminyak steakhouse for Australian grain-fed and dry-aged beef, with handmade pasta too. The two-floor room on Jl. Kayu Aya has a retractable roof upstairs. It serves dinner only.'),
    ('ginger-moon-canteen', '850511bef00c5c348f361c99a9db8e56', 'Chef Dean Keddell''s modern-Asian sharing restaurant on Seminyak''s Oberoi/Laksmana strip, open since 2012. You order several plates for the table rather than individual mains.'),
    ('glo-day-spa-salon-seminyak-seminyak', 'b98317d231e14bdc8ccd46ef99f5a7da', 'Opened in 2022 on Jl. Kayu Aya, this 480 sqm Western-style hair salon and day spa is managed by Australian senior stylists. The hair side does colour, cuts, keratin and bridal hair and make-up; the spa has treatment rooms, beauty rooms and a mani-pedi lounge.'),
    ('gusto-gelato', '48e69a2b32ed18410ea3b7e040a7bf3a', 'A gelateria and caffe that makes its own gelato in a wide range of flavours. They run from classic fior di latte to local twists like lemongrass, ginger and sesame. It also pours coffee in a calm sit-down space.'),
    ('hammerhead-fitness', '58736b473b173bb7571dbfd37409138c', 'Hammerhead is an old-school gym on the third floor of Kasih Market, Jl. Nakula: six hundred air-conditioned square metres and more than 80 stations. There''s a large cardio floor and a stretching area, plus four full-time trainers. Classes cover boxing, zumba, dangdut and belly dance.'),
    ('hog-wild-with-chef-bruno', '935426fec123a16d0334461a5392691b', 'Slow-cooked ribs are the draw at this casual American BBQ joint on Jalan Batu Belig in Kerobokan. Tables are family-style, the grilled food is low-fuss, and the menu is largely gluten-free.'),
    ('izzi-rooftop-lounge-and-restaurant-and-bar-and-shisha', 'fe94f7519a251fecf0def3a4e7168c9a', 'A rooftop bar, restaurant and shisha lounge at Batu Belig Square, looking over the ocean at sunset. The shisha list runs past 200 tobaccos; DJs play, and there are board games and a PlayStation.'),
    ('jari-menari-seminyak', '2e2b00fe31c14f14b4f9b92f60239898', 'A Seminyak massage house open since 2001, whose name means "dancing fingers". Its therapists, traditionally an all-male team, are trained in a rhythmic, flowing full-body technique. Its open-air rooms are set around a water wall and hand-carved stone.'),
    ('jasmine-aromatic-house', 'f6b40b7f6888eded2f5707dddb56716e', 'Minutes from the airport in Tuban, this Balinese day spa does aromatherapy massage, body scrubs and hair treatments. Showers and luggage storage are on site, and airport transfers are free.'),
    ('jiwa-bikram-yoga-bali-seminyak', 'c2e60a3aeb386abadcbe55b27ddaaf09', 'A hot-yoga studio in Petitenget, north Seminyak, teaching the classic Bikram 26-posture sequence (90 and 60 min). Sumits, hot Vinyasa, Ashtanga, Yin and hot Pilates fill out the timetable. Classes are small, in an unpretentious setting.'),
    ('kilo-kitchen-bali-seminyak', 'dbd22f1608f6336e6839c102f5fde54b', 'This outpost of Singapore''s Kilo is on Jl. Drupadi in Seminyak. The kitchen does Asian-fusion sharing plates such as squid-ink rice with soft-shell crab, beef-tongue tacos and Japanese ceviche. The space is tropical-industrial: concrete, wood and glass.'),
    ('kros-tennis-bali', 'c1e7d1c4d093bb56ab648b431231f9b1', 'Kros is an indoor smart tennis court on Jl. Patih Jelantik in Kuta, with AI tracking and performance readouts. Book the court, take coaching from beginner up or join women''s doubles; it''s open around the clock. The space also rents out for events and shoots.'),
    ('kynd-community', 'fd784101b6089da7a18ba3c18a5bfd69', 'Kynd is a big walk-in cafe on Jl. Petitenget for plant-forward brunch: smoothie bowls and colourful comfort food.'),
    ('la-casetta-bali', '68644ae7b236f164c3bc9049c1a5fad4', 'A home-style Italian restaurant in Umalas, open from breakfast through lunch to dinner. Bread and cornetti are baked daily, the pasta is fresh and the pizza is wood-fired. The setting is rustic and cozy.'),
    ('lagoon-spa-seminyak-seminyak', '60fb2744087906d10db670bfba4c020e', 'The spa at Villa Seminyak Estate & Spa has run since 2003. It has private spa villas and treatment rooms, plus a reflexology chill room. Its multi-hour Balinese ritual packages combine massage, scrub, flower bath, creambath and facial.'),
    ('ling-lings-bali', '25e3de70fa1092539b225c48f8e8ed40', 'An Asian-fusion restaurant and cocktail spot on Jl. Petitenget that leans Japanese and Korean. Sushi rolls, Korean tacos, bao buns and pork ribs are on the menu, and after dark there''s a DJ and a long drinks list.'),
    ('mades-warung-kuta', 'f51fe592d1bd0d7871ebfd4c29b0f446', 'Made''s Warung started as a roadside food stall in 1969 and has grown into a full Balinese restaurant on Jalan Pantai Kuta. Order the nasi campur or the ayam goreng bumbu Bali.'),
    ('mades-warung-seminyak', 'c1e6b1ea12968969b37b652fed1e341d', 'An Indonesian kitchen in Seminyak whose published menu includes traditional nasi campur, beef rendang and sate lilit. You book on the venue''s own site.'),
    ('makan-place-kuta-legian', 'b6271bb041f5a959210a47d9ed803d97', 'A Legian restaurant whose kitchen is described as modern Indonesian. The published menu includes Onion Toast. Booking is on the venue''s own site.'),
    ('mamasan-bali', '0ae176274fdccb23d96d3fb0432f222c', 'Chef Will Meyrick''s pan-Asian dining room in Seminyak cooks Southeast Asian street food, from Penang to Bangkok to Indonesian rendang. The room is 1920s Shanghai-style, with dark timber, green banquettes and chandeliers, and there''s a supper-club bar upstairs.'),
    ('mauri-restaurant', '24e6d224c077683e8e712abd6d34b75a', U&'This contemporary southern-Italian fine-dining restaurant on Jl. Petitenget is led by Apulian chef Maurizio Bombini. There''s a live kitchen, \00E0 la carte and seasonal tasting menus, and a rooftop hydroponic garden that supplies produce.'),
    ('merah-putih-indonesian-restaurant', 'fc6158c6cc1fa04241c0940319ffa008', 'Modern Indonesian dining on Jl. Petitenget since 2013, in a greenhouse-cathedral building by Inspiral Architects. It has 10-metre vaulted ceilings and rainwater-filtering columns. The kitchen does archipelago classics and contemporary takes, like Balinese yellowfin tuna and babi guling, with cocktails and wine.'),
    ('natys-restaurant-seminyak', '079f520f2f04ae4ab35fcbdc30acc4b2', 'At the front of this all-day restaurant on Jl. Kayu Aya (Oberoi/Eat Street), a fishmonger display lets you pick fresh fish for the grill. The menu is Indonesian, seafood and European, and it runs from breakfast to late night with cocktails and shisha.'),
    ('naughty-nuris-warung-seminyak', 'a007a4450af26bcde0da5ebe6af8e0dd', 'Naughty Nuri''s opened this Batu Belig branch of its Ubud original in 2016. It''s a casual warung for Balinese-style barbecued pork ribs and potent martinis.'),
    ('norii-japanese-restaurant-seminyak', 'a4a82189b9421e900706ab944112c019', 'Part of the Wonderspace group, this Japanese restaurant in Umalas does sushi, wagyu don and wagyu skewers. Robatayaki beef comes with charred vegetables, and the cocktails are built on yuzu, matcha and sake.'),
    ('pantai-kuta', 'da929c526d86fb492190f4d74abdea27', 'Pantai Kuta is a long stretch of sand in Badung, with surf breaks close to shore and sunsets by the water.'),
    ('pavilion-surf-club-kuta-legian', '351efc6140d10bfcc0866067b6764450', 'A Legian bar for cold beer during the game, wine with dinner and cocktails as the sun goes down over Legian Beach. At happy hour, cocktails are 140K each, buy one get one free. Booking is by WhatsApp.'),
    ('pison-petitenget', 'f46695cb9c4223bdda4f3aea159459ba', U&'Since 2014, Pison has been an Asian-Western caf\00E9 in a two-storey red-brick building on Jl. Petitenget, with high ceilings and exposed beams. All-day brunch has an Asian twist; the espresso-avocado and crispy pork belly fried rice are the orders. The coffee is locally sourced.'),
    ('potato-head-beach-club', '96e9e4dbd99703ac1b27b5330923d1c5', 'Potato Head Beach Club opened on Jl. Petitenget in 2010, behind an amphitheatre facade of around 5,000 vintage teakwood shutters by Andra Matin. DJs play at sunset. It anchors the Desa Potato Head resort and serves cocktails and an international-meets-Indonesian menu through the day.'),
    ('prana-spa-seminyak', '88758d01c9ef65486e70e1015866642f', 'A day spa at Impiana Private Villas (formerly The Villas) on Jl. Kunti, with Moorish-inspired interiors: domed ceilings, mosaic tiles and candle-lit corridors. The treatment menu is Indian- and Middle-Eastern-influenced, including traditional Ayurveda, and there are plunge pools, saunas and steam rooms.'),
    ('prana-spa-yoga-fitness-adjacent-seminyak', 'c2fb90ba310af9ebc808e6d48fbbd34e', 'The movement side of Prana Spa, the Moroccan-styled spa at Seminyak''s Impiana resort: yoga and fitness alongside the treatments.'),
    ('prana-yoga-seminyak', '81249faa2c7cf85e03fb9513c28d1c2f', 'Prana Spa''s dedicated Yoga Centre runs daily and private classes at Impiana Private Villas, Jl. Kunti 118X. Classes cover Vinyasa, Anusara, Power Vinyasa, Meditative Flow and Sivananda, in an ornate Indian/Middle-Eastern-inspired setting.'),
    ('pura-kehen', '1a063f744ed7d016916a9cb86c05be97', 'Pura Kehen is Bangli''s state temple, a multi-tiered terraced complex set into a hillside. Antique Chinese porcelain plates are set into its walls.'),
    ('rai-fitness-sunset-bali', '526fbeb681e5dc61f1b63a1c2e179fbc', 'Ade Rai opened this mega gym in 2013, with Life Fitness equipment and more than 40 Les Mills classes, plus zumba, pilates and yoga. There''s a pool, a sauna, basketball and futsal courts, and free parking. A day costs 55,000 IDR and a month 699,000.'),
    ('rai-fitness-sunset-road-seminyak', 'a5f64c7c8602785656e16724fcdefefc', 'This mega-gym on Sunset Road was founded by Ade Rai. It has an enormous Life Fitness weight floor, a big cardio section and 40+ Les Mills and other group classes. There''s a pool and a sauna, and parking is free.'),
    ('revive-pilates-umalas', 'a9dee85189f706c6b4352ae1f8340121', U&'Revive''s reformer Pilates studio in Umalas (there''s another in Canggu) runs a high-volume weekly schedule of reformer and mat classes, beginner to advanced. Its own formats include Gluteformer and Sweatformer, and the on-site caf\00E9 serves coffee, matcha and protein smoothies.'),
    ('revolver-seminyak', 'f2de294d977c03854653617c41eebef4', 'Down a lane off Jl. Kayu Aya, Revolver is a specialty-coffee cafe, open since 2012, that roasts its own beans locally. The interior is dark timber and brick, like a hidden bar, and the brunch is hearty.'),
    ('rip-curl-surf-school-kuta-legian', '0ccee329742b864cc8e6746720264e01', 'Rip Curl''s surf school runs guided lessons right off the sand in central Kuta, boards and instructors included. Kuta''s beach break is long and gentle.'),
    ('rob-peetoom-hair-spa-bali-seminyak', 'e80fb5f7c9c7e1befca472da538d6b63', 'Dutch salon brand Rob Peetoom opened this Bali outpost in 2012 at Petitenget St No. 16, overlooking rice paddies. Across three pavilions modelled on a Balinese village, it does hair styling, colour, make-up and hair-and-scalp rituals.'),
    ('saia-wellness-saia-pilates-umalas', '05b2573fa79a95c1c5ccc39e25d51073', 'The SAIA Wellness group runs this modern reformer Pilates studio in Umalas, open seven days a week. Classes on new reformers are capped at 7 clients, cover all levels and focus on form, and private sessions are available too.'),
    ('sangsaka', 'efd8e219b1c0a7106358597fa812f4f1', 'Kieran and Yunika Morland''s modern Indonesian restaurant cooks heritage recipes over a wood-fired oven and charcoal grills. Ingredients are regional, from across the archipelago. Beef rendang and smoked and grilled seafood are the dishes to order; the rooftop bar is called Diatas.'),
    ('sardine', 'e7ef69ce2a28f0e215242fb67935d69b', 'A seafood restaurant in a bamboo pavilion on Jl. Petitenget, looking out over a working rice paddy. The kitchen cooks fresh Indian Ocean catch, such as yellowfin tuna, snapper and scallops, with French technique and organic produce from its own Bedugul farm.'),
    ('sate-khas-senayan-beachwalk', 'b3128e4cbdae6917c79866c1517b0b3b', 'A Sarirasa Group chain restaurant cooking Indonesian classics in an air-conditioned mall, steps from Kuta beach. Satay, soto and gado-gado are on the menu: a family-safe Indonesian meal without hunting for a warung.'),
    ('sea-circus', 'fa871a65b5470309975cbe9962df3d34', U&'Open since 2010, this caf\00E9 and bar on Jl. Kayu Aya does all-day brunch, tacos and cocktails in a playful coral-pink-striped setting. The menu runs from acai bowls, benedicts and breakfast burritos to pulled-pork and baja fish tacos, with plenty of vegan and gluten-free options.'),
    ('shichirin-japanese-restaurant-seminyak', 'd5805b8a9bd000c7e548c6a80bac8ff0', 'A Japanese grill doing teppanyaki, gyukatsu, sushi and sashimi on Jl. Dewi Saraswati. It opened in January 2025.'),
    ('sisterfields', 'e12bfb89d8d97dab4f0c5fdc627a07d3', 'Opposite Seminyak Village on Jl. Kayu Cendana, Sisterfields is an Australian-style cafe doing all-day brunch and specialty coffee. The space is bright, tiled and minimalist, and plates include truffle scrambled eggs, bacon benedict, smashed avocado and acai bowls.'),
    ('soham-wellness-center-seminyak', '08156772c00e51ec129d864e044eb92a', 'An all-in-one wellness complex of about 2,500 sqm in Petitenget, with a fully equipped gym and a half-Olympic pool. The group-class timetable is broad (Pilates, HIIT, spinning, TRX, yoga, dance). A luxe spa, steam, sauna and hot/cold plunge pools sit alongside a healthy cafe.'),
    ('spring-spa-seminyak', 'e3250101a46750503b5012a39ba3c45f', 'The Seminyak branch of Spring Spa, an island-wide chain of bright salons for nails, waxing, massage and facials at fair prices.'),
    ('sundari-day-spa-seminyak', 'c0ddfa9f7619ea5fac930273df3435af', 'A Petitenget day spa, branded Sundari Wellness, that mixes modern and traditional techniques with natural products. The wide menu covers massages, body treatments, facials and mani-pedis, and it stays open late into the evening.'),
    ('the-goat-seminyak', '3f27075011b8347356d87209e2d9c311', 'This Seminyak bar is open for breakfast, lunch, dinner and late-night bites. Live music and DJs play every night from 8pm. Cake Cups are 75K IDR, and booking is on the venue''s own site.'),
    ('the-laneway-restaurant-seminyak', '4cf0a364a0f09cfe72359f917e08b674', 'A Seminyak restaurant whose published menu runs to 4 priced items. Arak Cocktail is 100K IDR. Booking is on the venue''s own site.'),
    ('the-legian-seminyak-wellness-yoga', 'f15ca23f534cd96647262620aea038f1', 'Wellness by The Legian, on Jl. Kayu Aya, is open to non-guests too. Daily classes cover yoga, pilates, meditation, HIIT, aqua-aerobics and spin; the gym has Technogym equipment and personal trainers. Steam and sauna rooms and a hot/cold plunge sit beside a relaxation lounge.'),
    ('the-shampoo-lounge-seminyak-seminyak', 'd3f03bc84d944de48f32766d0abe838d', 'An integrated salon, spa and barber on Jl. Raya Basangkasa, running since 2012. Hair covers cuts, colour, keratin and extensions; there are also nails, lashes, facials, massage, a men''s barber and a bridal hair-and-make-up team.'),
    ('therapy-hair-spa-seminyak', '977ac3fa15b47ae44f78b3d3e2713939', 'Therapy''s Seminyak branch, where a hair salon and a day spa share one address. Cuts and colour sit alongside facials and massage.'),
    ('think-pink-nails-seminyak', '0bacaf223b92bc523486a203b3a8d017', 'Think Pink runs its Seminyak flagship on Jl. Batu Belig, doing manicures, pedicures, BIAB and nail art. It also does hair and skin, and there''s a private Netflix room for treatments. A separate Think Pink branch runs in Canggu.'),
    ('think-pink-salon-and-nails-bali', '374db229c0ea5c0dab355a4b4cd58fcb', 'A nail salon in Batu Belig with an extensive polish range for manicures, pedicures, BIAB and nail art. Hair and skin services run alongside, and there''s a private room for watching Netflix during a treatment.'),
    ('to-the-moon-cafe', '537eb67ba20b9d25bee29b9901ed3b66', 'Sushi rolls share the menu with Western plates at this Umalas cafe on Jl. Bumbak: beef and salmon steaks, gourmet burgers, pancakes and smoothie bowls. It does takeaway and delivery as well as dine-in, and parking is free.'),
    ('vincent-nigita', '1ff11ced39cab7a4e2eca8c4fed03212', 'Bordeaux-trained pastry chef Vincent Nigita runs this French patisserie inside Kanvaz resort, pairing classical French technique with Indonesian flavours. Classic pastries sit alongside plated desserts in a weekend tea room.'),
    ('w-bali-wellness-yoga', 'cec470e0608b98e8a3f1dfcbc01ce900', 'W Bali''s yoga and class programme runs out of FIT, the resort''s 24-hour gym overlooking the Indian Ocean. Weekly classes cover Hatha, Vinyasa and Power yoga, with sunrise sessions on the schedule. There''s an oxygen room too, and AWAY Spa runs private meditation sessions.'),
    ('waroeng-bernadette', '679fbbae387d1743d1b951b68f920e55', 'This homestyle Indonesian warung on Jl. Kayu Aya cooks everything traditionally from scratch, and the spice level is adjustable. Its 12-hour slow-cooked beef rendang leads a menu of oxtail soup, rawon, corn fritters and plenty of vegetarian and vegan options.'),
    ('waroeng-sulawesi-petitenget', 'e979971779b67cbcdc14f759ef1374f5', 'A self-service warung on Petitenget with home-cooked Sulawesi and Indonesian dishes. You walk the counter and build a plate on white, yellow or red rice, and the regional plates run spicy.'),
    ('warung-enys', 'ee785c6a9a3d4cd3da0eaefdc47e2714', 'Ibu Eny and her husband run this small family warung on Petitenget, with an open kitchen and mostly local produce, cooked fresh daily. Nasi campur is the plate to order.'),
    ('warung-kampung-legian', '01533fed36eedcf2cba0c3fb9ecba7e1', 'Nasi goreng and mie goreng at everyday prices, from a Balinese-run local warung in Legian.'),
    ('warung-melati-nakula', 'c1a020f008b5e06c3d4114b07c8652e6', U&'In a quiet alley on the Seminyak\2013Legian border, this family-run warung cooks Javanese food. The kitchen starts early in the morning, so nasi campur and sides are ready by late morning. It is advertised as non-MSG and halal.'),
    ('warung-nia-balinese-food-and-pork-ribs', '04f098df388222c6ac394c7c3fb0580c', 'A casual Balinese warung in Kayu Aya Square on Jl. Kayu Aya, the Oberoi strip. The pork ribs are slow-cooked and spice-marinated, sold by weight with a choice of chilli levels. Babi guling, satay and rijsttafel are on the menu too.'),
    ('warung-taman-bambu', 'dfc5653081af1f85e261e2c2fbc8ca8e', 'Off the main road, this pick-and-mix warung has a calmer, garden-style setting. You choose dishes from a cabinet, and nasi campur and Indonesian home cooking are the core.'),
    ('warung-wardani', '0749c9ebf5e55f6fd190095586ef5408', 'Decades old and open in the daytime only, this Denpasar warung on Jl. Yudistira serves halal Balinese food. The nasi campur Bali comes with items such as satay, dendeng and vegetables over rice.'),
    ('watercress-seminyak', 'ddd0ff62264cab7e0c4bf1b18adc359e', 'A spacious, work-friendly brunch spot on Seminyak''s northern edge, in Batu Belig. It suits a longer catch-up or a laptop morning.'),
    ('yoga-108-bali-kuta-legian', '0c3b630ce25a938ae59d780e34d49177', 'A drop-in yoga studio in the Kuta-Legian area, for a single class without committing to a multi-day retreat.'),
    ('yoga-108-bali-seminyak', '36a1645cf4f7598d2d4ef28a955fcbcb', 'An unpretentious drop-in studio at Jl. Drupadi 108 in central Seminyak, with daily classes for all levels. Hatha, Vinyasa, Ashtanga, Yin and meditation run alongside a Yoga Alliance 200-hour teacher training, workshops and retreats.'),
    ('you-spa-umalas', '026d4edc603afeb78d44c2f4d0bf125a', 'An Umalas day spa that works with its own line of natural products. Treatments include Balinese and holistic body massages, body masks, facials, and hair and nail care. The spa''s own options include a Sport Massage and a "Black Room" session.')
  ) as d(slug, old_md5, val)
  where v.slug = d.slug and v.status = 'active' and v.publication_status = 'published'
    and case when d.old_md5 is null then (v.why_its_here is null or length(trim(v.why_its_here)) = 0) else md5(v.why_its_here) = d.old_md5 end;
  get diagnostics n = row_count; if n <> 95 then raise exception 'wave-seminyak-kuta-bali-2026-10-08 why_its_here: expected 95 rows, got %', n; end if;

